                if (!item) return;
                if (!confirm('Xoá biểu đồ này?')) return;
                try {
                    const { error } = await sb.from(WR3T1_TABLE).delete().eq('id', item.id);
                    if (error) throw error;
                    wr3t1Items = wr3t1Items.filter(it => it.id !== item.id);
                    wr3t1RenderItemList();
                } catch (e2) { alert('Xoá thất bại: ' + e2.message); }
